SELECT tblCase.*, qryMatter.Balance, qryInvoiceRPT.MatterID, qryInvoiceRPT.Date2, qryInvoiceRPT.Pay_Outlay, qryInvoiceRPT.Charge, qryInvoiceRPT.Payment, qryInvoiceRPT.[Case No], qryInvoiceRPT.[Balance Due Date], qryInvoiceRPT.[Past Due], qryInvoiceRPT.[Long Term Collections], qryInvoiceRPT.chkBalanceDue, qryInvoiceRPT.[Billing Notes], fncRunningDebit([tblcase].[CaseID],qryInvoiceRPT.[Date2],qryInvoiceRPT.[MatterID]) AS RunningDebit, fncRunningCredit([tblcase].[CaseID],qryInvoiceRPT.[Date2],qryInvoiceRPT.[MatterID]) AS RunningCredit, [RunningDebit]-[RunningCredit] AS RunningBalance, qryMatter.OrderNr
FROM (qryInvoiceRPT LEFT JOIN tblCase ON qryInvoiceRPT.CaseID = tblCase.CaseID) LEFT JOIN qryMatter ON qryInvoiceRPT.MatterID = qryMatter.MatterID
ORDER BY tblCase.CaseID, qryInvoiceRPT.MatterID;